// Package subscriptions is a multi-provider subscription hub: providers
// publish plans priced per billing period; subscribers pay per period,
// with deterministic renewal, grace, expiration and cancellation rules;
// other realms and off-chain services gate access on Entitled /
// EntitledFor, which is the integration surface this realm exists to
// provide.
//
// THE BILLING MODEL, COMPLETELY:
//
//	Subscribe (payable, exact price)  : creates the subscription, pays
//	                                    period 1. paidThrough = height
//	                                    + periodBlocks.
//	Renew (payable, exact price)      : extends paidThrough by exactly
//	                                    one periodBlocks, FROM
//	                                    paidThrough — never from the
//	                                    current height — so period
//	                                    boundaries are fixed at
//	                                    Subscribe time and never drift.
//	Entitlement                       : height < paidThrough. Nothing
//	                                    else. Status does not enter
//	                                    into it: a cancelled
//	                                    subscription stays entitled to
//	                                    what it already paid for.
//	Renewal window                    : a renewal is accepted iff BOTH
//	                    paidThrough - height <= periodBlocks   (early bound)
//	                    height < paidThrough + periodBlocks    (late bound)
//	                                    The early bound caps prepayment
//	                                    at one full unstarted period —
//	                                    a second Renew straight after a
//	                                    first is refused, which is what
//	                                    makes an accidental duplicate
//	                                    payment structurally impossible
//	                                    rather than merely unlikely.
//	                                    The late bound is the grace
//	                                    window: renewing after lapse
//	                                    extends from paidThrough, so it
//	                                    back-pays the lapsed span to
//	                                    keep the original schedule and
//	                                    buys paidThrough + periodBlocks
//	                                    - height further blocks — always
//	                                    at least one, because the bound
//	                                    is exclusive (audit finding Y2).
//	                                    A lapsed subscriber who prefers
//	                                    a fresh full period may Cancel
//	                                    and Subscribe again at the same
//	                                    total price; Subscribe's refusal
//	                                    message states both options.
//	Expire (permissionless valve)     : once height >= paidThrough +
//	                                    periodBlocks, anyone may mark
//	                                    the subscription Expired. No
//	                                    funds move — every payment
//	                                    settled when it was made. The
//	                                    valve exists so the
//	                                    plan|subscriber slot frees
//	                                    without depending on either
//	                                    party, and Subscribe itself
//	                                    collapses an expired incumbent,
//	                                    so a fresh start never depends
//	                                    on housekeeping having run. The
//	                                    renewable and expirable height
//	                                    sets partition exactly: no
//	                                    height is in both or neither.
//	Cancel (subscriber only)          : Active -> Cancelled. Terminal.
//	                                    No refund — payments settle to
//	                                    the provider at payment time,
//	                                    and what was bought (entitlement
//	                                    through paidThrough) stays
//	                                    bought. What cancellation ends
//	                                    is the OBLIGATION: a Cancelled
//	                                    subscription can never be
//	                                    renewed, by the subscriber or
//	                                    anyone else.
//	RetirePlan (provider only)        : no new Subscribes, no renewals.
//	                                    Existing entitlements run to
//	                                    paidThrough untouched. Refusing
//	                                    renewals on a retired plan is
//	                                    subscriber protection: nobody
//	                                    can keep paying for a service
//	                                    whose provider announced its
//	                                    end.
//
// The obligation is therefore explicit on chain at every moment: a
// subscription owes nothing (there is no pull payment and no debt — a
// lapse simply ends entitlement), and the realm owes the subscriber
// exactly `paidThrough - height` blocks of entitlement, queryable by
// anyone via PaidThrough / Entitled / EntitledFor.
//
// WHO PAYS WHOM. Payments settle immediately: price - fee is credited
// to the provider's claimable balance, fee to the protocol pot, both
// inside the same feeledger the sibling realms use. There is no escrow:
// H == U + F at all times (plus out-of-band surplus, recoverable by
// SweepDenom above the Liabilities reserve). The renewal caller must be
// the subscriber — a third party cannot extend someone else's
// subscription, which closes both a consent problem (an unwanted gift
// re-arms a lapsing obligation) and a griefing edge (spending pennies
// to keep a victim's slot occupied).
//
// FEES follow the house pattern exactly: a compile-time MaxFeeBps
// ceiling, the current fee snapshotted into the PLAN at CreatePlan
// (provider consents via its own maxFeeBps argument), copied into the
// subscription at Subscribe, and charged at every payment from the
// PROVIDER's side. A later SetFeeBps touches only plans created
// afterwards; no existing plan or subscription can have its fee moved
// by anyone.
//
// REALM-CALLER CAVEAT, inherited from the siblings verbatim: coinio's
// receipt guard admits only EOA payers, so subscribers are EOAs;
// assertNoSend reads the ORIGIN envelope, so every non-payable function
// refuses any transaction that attached coins anywhere. Providers may
// be EOAs or realms, but a realm provider must expose its own crossing
// path to Claim, or what it earns is stranded (see RegisterService's
// caveat in service_market — the same three obligations apply).
package subscriptions

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/coinio"
	"gno.land/p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/feeledger"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
)

// Denom is the only asset this realm accepts.
const Denom = "ugnot"

// MaxFeeBps is the hard protocol-fee cap: 1000 bps = 10%.
const MaxFeeBps = int64(1000)

// Plan status values.
const (
	PlanActive  = "active"
	PlanRetired = "retired"
)

// Subscription status values. Cancelled and Expired are terminal.
const (
	SubActive    = "active"
	SubCancelled = "cancelled"
	SubExpired   = "expired"
)

// Input bounds.
const (
	MaxTitleLen = 80
	MaxDescLen  = 2000
	MinPrice    = int64(1)

	// MinPeriodBlocks/MaxPeriodBlocks bound a plan's billing period:
	// ~40 seconds to ~1 year at pearl's observed ~4.2s blocks. The
	// floor keeps a hostile plan from turning renewal into a
	// per-block treadmill; the ceiling keeps paidThrough arithmetic
	// far from overflow even at maximum prepayment.
	MinPeriodBlocks = int64(10)
	MaxPeriodBlocks = int64(7500000)

	// MaxPlansPerProvider bounds catalog monopolization by a single
	// address — the finding that was RED in permission_registry and
	// service_registry, carried from the start here.
	MaxPlansPerProvider = 20

	// MaxSubsPerSubscriber bounds one account's open-subscription
	// state. Terminal subscriptions free their slot.
	MaxSubsPerSubscriber = 100

	// RenderLimit bounds every rendered list — an unbounded Render
	// was YELLOW in three prior audits.
	RenderLimit = 20
)

type plan struct {
	id           int64
	provider     address
	title        string
	description  string
	price        int64
	periodBlocks int64
	feeBps       int64 // snapshotted at creation, charged at every payment
	status       string
	subs         int64 // lifetime count, never decremented
}

type sub struct {
	id           int64
	planID       int64
	subscriber   address
	provider     address // copied at Subscribe; never re-read from the plan
	price        int64   // copied at Subscribe; a plan is immutable anyway
	periodBlocks int64   // copied at Subscribe
	feeBps       int64   // copied at Subscribe from the plan's snapshot
	status       string
	paidThrough  int64 // absolute height; entitlement = height < paidThrough
	periods      int64 // lifetime paid-period count
}

var (
	admin        address // may set fee, fee recipient, stage successor
	pendingAdmin address // staged by TransferAdmin, completes via AcceptAdmin
	feeRecipient address // may withdraw fees and sweep surplus
	feeBps       int64   // fee snapshotted into NEW plans

	self     address // this realm's address, captured at deploy
	nextPlan int64
	nextSub  int64

	plans       = avl.NewTree() // padID(id)                 -> *plan
	subs        = avl.NewTree() // padID(id)                 -> *sub
	activeByKey = avl.NewTree() // padID(planID)|subscriber  -> int64 sub id, while Active
	latestByKey = avl.NewTree() // padID(planID)|subscriber  -> most recent sub id, never removed
	providerNum = avl.NewTree() // address -> *int64, live plans per provider
	subNum      = avl.NewTree() // address -> *int64, Active subs per subscriber
	ledger      = feeledger.MustNew(MaxFeeBps)
)

func init() {
	admin = unsafe.OriginCaller()
	feeRecipient = admin
	self = unsafe.CurrentRealm().Address()
}

// --- provider side ---

// CreatePlan publishes a subscription plan and returns its id. No coins
// are accepted; the storage deposit the caller pays is the anti-spam.
// The current protocol fee is snapshotted into the plan and must not
// exceed maxFeeBps, the ceiling the provider signed for — pass
// MaxFeeBps to accept any legal fee. Plans are immutable once created:
// price and period changes are a new plan, so nothing a subscriber
// agreed to can move underneath them.
func CreatePlan(cur realm, title, description string, price, periodBlocks, maxFeeBps int64) int64 {
	assertNoSend()
	provider := cur.Previous().Address()

	if title == "" || len(title) > MaxTitleLen {
		panic("title must be 1.." + itoa(int64(MaxTitleLen)) + " bytes")
	}
	if len(description) > MaxDescLen {
		panic("description too long")
	}
	if price < MinPrice {
		panic("price must be at least " + itoa(MinPrice) + Denom)
	}
	if periodBlocks < MinPeriodBlocks || periodBlocks > MaxPeriodBlocks {
		panic("periodBlocks must be in [" + itoa(MinPeriodBlocks) + ", " +
			itoa(MaxPeriodBlocks) + "]")
	}
	if feeBps > maxFeeBps {
		panic("current fee " + itoa(feeBps) + " bps exceeds the caller's maximum " +
			itoa(maxFeeBps))
	}
	n := counter(providerNum, provider)
	if *n >= MaxPlansPerProvider {
		panic("per-provider plan limit reached")
	}

	id := nextPlan
	nextPlan++
	plans.Set(padID(id), &plan{
		id:           id,
		provider:     provider,
		title:        title,
		description:  description,
		price:        price,
		periodBlocks: periodBlocks,
		feeBps:       feeBps,
		status:       PlanActive,
	})
	*n++

	chain.Emit("PlanCreated",
		"planId", itoa(id),
		"provider", provider.String(),
		"price", itoa(price),
		"periodBlocks", itoa(periodBlocks),
		"feeBps", itoa(feeBps),
	)
	return id
}

// RetirePlan takes a plan off the market: no new subscriptions and no
// renewals. Provider only. Existing entitlements run to their
// paidThrough untouched; refusing renewals is subscriber protection —
// nobody keeps paying for a service whose provider announced its end.
// The provider's plan-quota slot frees.
func RetirePlan(cur realm, planID int64) {
	assertNoSend()
	caller := cur.Previous().Address()
	p := mustGetPlan(planID)
	if caller != p.provider {
		panic("only the provider may retire a plan")
	}
	if p.status != PlanActive {
		panic("plan is not active")
	}
	p.status = PlanRetired
	*counter(providerNum, p.provider)--
	chain.Emit("PlanRetired", "planId", itoa(planID), "provider", p.provider.String())
}

// --- subscriber side ---

// Subscribe pays for the first billing period of a plan and returns the
// new subscription id. The transaction must attach EXACTLY the plan's
// price in ugnot — over- and underpayment are both refused, so a
// mistaken double-attach cannot silently become a donation. One
// subscriber holds at most one live subscription per plan: if an Active
// one exists the call is refused (the renewal path is Renew, never a
// second Subscribe — that is the duplicate-payment guard at the
// identity level); an incumbent past its grace window is collapsed to
// Expired in place, so a fresh start never waits on housekeeping.
//
// The payment settles immediately: price minus the plan's snapshotted
// fee to the provider's claimable balance, fee to the protocol pot.
// Entitlement runs from this block: paidThrough = height + periodBlocks.
func Subscribe(cur realm, planID int64) int64 {
	subscriber, amount := coinio.Receive(0, cur, Denom)
	p := mustGetPlan(planID)
	if p.status != PlanActive {
		panic("plan is not active")
	}
	if amount != p.price {
		panic("send exactly the plan price: " + itoa(p.price) + Denom)
	}

	key := padID(planID) + "|" + subscriber.String()
	if v := activeByKey.Get(key); v != nil {
		inc := mustGetSub(v.(int64))
		if runtime.ChainHeight() >= inc.paidThrough+inc.periodBlocks {
			expireInPlace(inc)
		} else if runtime.ChainHeight() >= inc.paidThrough {
			panic("subscription " + itoa(inc.id) + " to this plan is lapsed but renewable: " +
				"Renew back-pays the lapsed span and keeps the schedule; " +
				"Cancel then Subscribe restarts fresh at the same price")
		} else {
			panic("an active subscription to this plan already exists: renew it instead")
		}
	}
	n := counter(subNum, subscriber)
	if *n >= MaxSubsPerSubscriber {
		panic("per-subscriber subscription limit reached")
	}

	ledger.MustDeposit(p.provider.String(), amount, p.feeBps)

	id := nextSub
	nextSub++
	subs.Set(padID(id), &sub{
		id:           id,
		planID:       planID,
		subscriber:   subscriber,
		provider:     p.provider,
		price:        p.price,
		periodBlocks: p.periodBlocks,
		feeBps:       p.feeBps,
		status:       SubActive,
		paidThrough:  runtime.ChainHeight() + p.periodBlocks,
		periods:      1,
	})
	activeByKey.Set(key, id)
	latestByKey.Set(key, id)
	*n++
	p.subs++

	chain.Emit("Subscribed",
		"subId", itoa(id),
		"planId", itoa(planID),
		"subscriber", subscriber.String(),
		"provider", p.provider.String(),
		"amount", itoa(amount),
		"paidThrough", itoa(runtime.ChainHeight()+p.periodBlocks),
	)
	return id
}

// Renew pays for the next billing period of the caller's own
// subscription. The transaction must attach exactly the subscription's
// price. The renewal window is deterministic and stated in the header:
// accepted iff paidThrough - height <= periodBlocks (at most one full
// unstarted period prepaid — the duplicate-payment bound) and height <
// paidThrough + periodBlocks (the grace bound, exclusive — a renewal
// always buys at least one block). Extension is always
// FROM paidThrough, so period boundaries never drift, and a renewal
// inside grace covers the lapsed span — that is the price of keeping
// the original schedule, and it is the documented, deterministic
// choice.
func Renew(cur realm, subID int64) {
	payer, amount := coinio.Receive(0, cur, Denom)
	s := mustGetSub(subID)
	if payer != s.subscriber {
		panic("only the subscriber may renew")
	}
	if s.status != SubActive {
		panic("subscription is " + s.status)
	}
	p := mustGetPlan(s.planID)
	if p.status != PlanActive {
		panic("plan is retired; the paid period runs to its end but cannot be renewed")
	}
	if amount != s.price {
		panic("send exactly the subscription price: " + itoa(s.price) + Denom)
	}
	h := runtime.ChainHeight()
	if s.paidThrough-h > s.periodBlocks {
		panic("too early: at most one unstarted period may be prepaid; renewable from height " +
			itoa(s.paidThrough-s.periodBlocks))
	}
	if h >= s.paidThrough+s.periodBlocks {
		panic("grace window over; the subscription is expirable, subscribe afresh")
	}

	ledger.MustDeposit(s.provider.String(), amount, s.feeBps)
	s.paidThrough += s.periodBlocks
	s.periods++

	chain.Emit("Renewed",
		"subId", itoa(subID),
		"subscriber", s.subscriber.String(),
		"amount", itoa(amount),
		"paidThrough", itoa(s.paidThrough),
	)
}

// Cancel ends the caller's own subscription. Terminal: it can never be
// renewed afterwards, by anyone. No refund and no funds move — every
// payment settled when it was made, and the entitlement already bought
// (height < paidThrough) remains until it runs out. The plan slot and
// the subscriber's quota slot free immediately.
func Cancel(cur realm, subID int64) {
	assertNoSend()
	caller := cur.Previous().Address()
	s := mustGetSub(subID)
	if caller != s.subscriber {
		panic("only the subscriber may cancel")
	}
	if s.status != SubActive {
		panic("subscription is " + s.status)
	}
	s.status = SubCancelled
	releaseSlots(s)
	chain.Emit("Cancelled",
		"subId", itoa(subID),
		"subscriber", s.subscriber.String(),
		"paidThrough", itoa(s.paidThrough),
	)
}

// Expire marks a lapsed subscription Expired once its grace window is
// over: height >= paidThrough + periodBlocks. Permissionless by design —
// like the sibling realms' valves, no slot's liveness may depend on
// either party showing up. No funds move.
func Expire(cur realm, subID int64) {
	assertNoSend()
	s := mustGetSub(subID)
	if s.status != SubActive {
		panic("subscription is " + s.status)
	}
	if runtime.ChainHeight() < s.paidThrough+s.periodBlocks {
		panic("not expirable: grace runs through height " +
			itoa(s.paidThrough+s.periodBlocks-1))
	}
	expireInPlace(s)
}

// --- payouts ---

// Claim sends amount ugnot of the caller's claimable balance back to
// the caller. Providers earn into this balance at every payment.
func Claim(cur realm, amount int64) {
	assertNoSend()
	caller := cur.Previous().Address()
	if err := ledger.Withdraw(caller.String(), amount); err != nil {
		panic(err)
	}
	coinio.Payout(0, cur, caller, Denom, amount)
	chain.Emit("Claim", "to", caller.String(), "amount", itoa(amount))
}

// ClaimAll sends the caller's entire claimable balance back to the
// caller. Fails if there is nothing to claim.
func ClaimAll(cur realm) {
	assertNoSend()
	caller := cur.Previous().Address()
	amount, err := ledger.WithdrawAll(caller.String())
	if err != nil {
		panic(err)
	}
	if amount == 0 {
		panic("nothing to claim")
	}
	coinio.Payout(0, cur, caller, Denom, amount)
	chain.Emit("Claim", "to", caller.String(), "amount", itoa(amount))
}

// WithdrawFees sends the accrued fee pot to the fee recipient. Only the
// fee recipient may call it, and only the pot moves.
func WithdrawFees(cur realm) {
	assertNoSend()
	if cur.Previous().Address() != feeRecipient {
		panic("fee recipient only")
	}
	amount := ledger.WithdrawFees()
	if amount == 0 {
		panic("no fees accrued")
	}
	coinio.Payout(0, cur, feeRecipient, Denom, amount)
	chain.Emit("FeesWithdrawn", "to", feeRecipient.String(), "amount", itoa(amount))
}

// SweepDenom recovers out-of-band coins (sent by raw bank transfer,
// outside any entrypoint) to the fee recipient. For the ledger denom
// the reserve is Liabilities() — user balances and the fee pot are
// structurally unreachable. Fee recipient only.
func SweepDenom(cur realm, denom string) {
	assertNoSend()
	if cur.Previous().Address() != feeRecipient {
		panic("fee recipient only")
	}
	reserve := int64(0)
	if denom == Denom {
		reserve = ledger.Liabilities()
	}
	// coinio.Sweep itself aborts when nothing sits above the reserve.
	swept := coinio.Sweep(0, cur, feeRecipient, denom, reserve)
	chain.Emit("SurplusSwept", "to", feeRecipient.String(), "coins", itoa(swept)+denom)
}

// --- administration ---

// SetFeeBps sets the protocol fee snapshotted into FUTURE plans.
// Bounded by MaxFeeBps; existing plans and subscriptions are untouched
// — their fee was fixed the moment the provider consented to it.
func SetFeeBps(cur realm, bps int64) {
	assertNoSend()
	assertAdmin(cur.Previous().Address())
	if bps < 0 || bps > MaxFeeBps {
		panic("fee must be in [0, " + itoa(MaxFeeBps) + "] bps")
	}
	old := feeBps
	feeBps = bps
	chain.Emit("FeeChanged", "oldBps", itoa(old), "newBps", itoa(bps))
}

// SetFeeRecipient points future fee withdrawals and sweeps at a new
// address. Admin only. The zero address is refused — it would strand
// the pot.
func SetFeeRecipient(cur realm, recipient address) {
	assertNoSend()
	assertAdmin(cur.Previous().Address())
	var zero address
	if recipient == zero {
		panic("fee recipient must not be the zero address")
	}
	old := feeRecipient
	feeRecipient = recipient
	chain.Emit("FeeRecipientChanged", "old", old.String(), "new", recipient.String())
}

// TransferAdmin stages a two-step admin handover. The successor holds
// nothing until AcceptAdmin.
func TransferAdmin(cur realm, successor address) {
	assertNoSend()
	assertAdmin(cur.Previous().Address())
	var zero address
	if successor == zero {
		panic("successor must not be the zero address")
	}
	pendingAdmin = successor
	chain.Emit("AdminTransferStaged", "from", admin.String(), "to", successor.String())
}

// AcceptAdmin completes the handover; only the staged successor may.
func AcceptAdmin(cur realm) {
	assertNoSend()
	caller := cur.Previous().Address()
	if caller != pendingAdmin {
		panic("only the staged successor may accept")
	}
	old := admin
	admin = caller
	var zero address
	pendingAdmin = zero
	chain.Emit("AdminTransferred", "from", old.String(), "to", admin.String())
}

// --- views ---

// Entitled reports whether the subscription's paid entitlement covers
// the current block: height < paidThrough. Status deliberately does not
// enter into it — a cancelled subscriber keeps what they paid for, and
// an expirable-but-unexpired one has already lapsed here.
func Entitled(subID int64) bool {
	s := mustGetSub(subID)
	return runtime.ChainHeight() < s.paidThrough
}

// EntitledFor reports whether subscriber currently holds paid
// entitlement to planID, through their MOST RECENT subscription to it.
// This is the one-call integration surface for other realms and
// services, and it honors the entitlement contract across status: a
// cancelled subscription keeps answering true until its paidThrough —
// what was bought stays bought (audit finding Y1). One self-inflicted
// edge is fail-closed: cancelling a prepaid subscription and
// re-subscribing at once points this surface at the NEW, earlier
// paidThrough; the old subscription's remaining span stays queryable
// per-id via Entitled.
func EntitledFor(planID int64, subscriber address) bool {
	v := latestByKey.Get(padID(planID) + "|" + subscriber.String())
	if v == nil {
		return false
	}
	return Entitled(v.(int64))
}

// ActiveSubID returns the caller-facing id of subscriber's live
// subscription to planID, or (0, false) if none is Active.
func ActiveSubID(planID int64, subscriber address) (int64, bool) {
	v := activeByKey.Get(padID(planID) + "|" + subscriber.String())
	if v == nil {
		return 0, false
	}
	return v.(int64), true
}

// PlanInfo returns a plan's public fields.
func PlanInfo(planID int64) (provider address, title string, price, periodBlocks, planFeeBps int64, status string, lifetimeSubs int64) {
	p := mustGetPlan(planID)
	return p.provider, p.title, p.price, p.periodBlocks, p.feeBps, p.status, p.subs
}

// SubInfo returns a subscription's public fields.
func SubInfo(subID int64) (planID int64, subscriber, provider address, price, paidThrough, periods int64, status string) {
	s := mustGetSub(subID)
	return s.planID, s.subscriber, s.provider, s.price, s.paidThrough, s.periods, s.status
}

// PaidThrough returns the absolute height a subscription is paid to.
func PaidThrough(subID int64) int64 { return mustGetSub(subID).paidThrough }

// RenewableFrom returns the earliest height at which Renew will accept
// a payment for this subscription, and the last height at which it
// still will (inclusive) — the deterministic window, precomputed for
// integrators. From until+1 the subscription is expirable instead; the
// two sets partition exactly.
func RenewableFrom(subID int64) (from, until int64) {
	s := mustGetSub(subID)
	return s.paidThrough - s.periodBlocks, s.paidThrough + s.periodBlocks - 1
}

func Admin() address            { return admin }
func PendingAdmin() address     { return pendingAdmin }
func FeeRecipient() address     { return feeRecipient }
func FeeBps() int64             { return feeBps }
func NumPlans() int64           { return nextPlan }
func NumSubs() int64            { return nextSub }
func UsersTotal() int64         { return ledger.UsersTotal() }
func FeesAccrued() int64        { return ledger.FeesAccrued() }
func Liabilities() int64        { return ledger.Liabilities() }
func BalanceOf(a address) int64 { return ledger.BalanceOf(a.String()) }
func Address() address          { return self }
func Held() int64               { return coinio.HeldAt(self, Denom) }

// --- render ---

func Render(path string) string {
	if path == "" {
		return renderHome()
	}
	return "unknown page; try the realm root"
}

func renderHome() string {
	out := "# subscriptions\n\n"
	out += "Provider-published plans, per-period payment, deterministic " +
		"renewal, grace, expiration and cancellation. Entitlement is " +
		"`height < paidThrough`, queryable by anyone.\n\n"
	out += "- plans: " + itoa(nextPlan) + "\n"
	out += "- subscriptions: " + itoa(nextSub) + "\n"
	out += "- provider balances: " + itoa(ledger.UsersTotal()) + Denom + "\n"
	out += "- fees accrued: " + itoa(ledger.FeesAccrued()) + Denom + "\n"
	out += "- current fee for new plans: " + itoa(feeBps) + " bps (cap " +
		itoa(MaxFeeBps) + ")\n\n"

	if nextPlan == 0 {
		return out + "No plans yet.\n"
	}
	out += "## newest plans\n\n"
	shown := int64(0)
	for id := nextPlan - 1; id >= 0 && shown < RenderLimit; id-- {
		p := mustGetPlan(id)
		out += "- #" + itoa(p.id) + " **" + sanitize.InlineText(p.title) +
			"** — " + itoa(p.price) + Denom + " / " + itoa(p.periodBlocks) +
			" blocks, " + p.status + ", provider `" + p.provider.String() +
			"`, " + itoa(p.subs) + " lifetime subs\n"
		shown++
	}
	if nextPlan > shown {
		out += "\n(" + itoa(nextPlan-shown) + " older plans not shown)\n"
	}
	return out
}

// --- internals ---

// expireInPlace flips an Active subscription to Expired and frees its
// slots. Callers have already established expirability.
func expireInPlace(s *sub) {
	s.status = SubExpired
	releaseSlots(s)
	chain.Emit("SubscriptionExpired",
		"subId", itoa(s.id),
		"subscriber", s.subscriber.String(),
		"paidThrough", itoa(s.paidThrough),
	)
}

// releaseSlots removes the plan|subscriber activity index entry and
// decrements the subscriber's quota counter. Exactly once per terminal
// transition, which both terminal paths guarantee by requiring
// SubActive first.
func releaseSlots(s *sub) {
	activeByKey.Remove(padID(s.planID) + "|" + s.subscriber.String())
	*counter(subNum, s.subscriber)--
}

func assertNoSend() {
	if len(unsafe.OriginSend()) != 0 {
		panic("this function does not accept coins")
	}
}

func assertAdmin(caller address) {
	if caller != admin {
		panic("admin only")
	}
}

func mustGetPlan(id int64) *plan {
	v := plans.Get(padID(id))
	if v == nil {
		panic("unknown plan id")
	}
	return v.(*plan)
}

func mustGetSub(id int64) *sub {
	v := subs.Get(padID(id))
	if v == nil {
		panic("unknown subscription id")
	}
	return v.(*sub)
}

// counter returns the persistent per-address counter in tree,
// allocating a zero on first use.
func counter(tree *avl.Tree, a address) *int64 {
	k := a.String()
	if v := tree.Get(k); v != nil {
		return v.(*int64)
	}
	n := new(int64)
	tree.Set(k, n)
	return n
}

func padID(id int64) string {
	s := strconv.FormatInt(id, 10)
	for len(s) < 12 {
		s = "0" + s
	}
	return s
}

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

// Package spendbook is a pure allowance primitive for realms that need to
// let one party spend another party's funds, up to a bounded amount, over
// many transactions. It is to *delegated spending* what duebook is to
// *time*: it holds no coins, performs no effects, imports no chain APIs,
// and owns no package-level state. The importing realm owns a *Book,
// supplies the clock, and performs its own effects.
//
// # Why this package exists
//
// The ecosystem's existing allowance primitive,
// gno.land/p/jaekwon/allowancesender/v0, is scoped to a single call and
// says so in its own documentation:
//
//	"Allowance survives across N txs but not N+1 txs." Use a session
//	counter pattern in the granter realm; this package's Close is
//	binary, not deadline-based.
//
// It then declines block-height expiry on the grounds that it "would
// require runtime cooperation". That is true only for a package that reads
// the clock itself. spendbook does not: every operation takes `now` as an
// argument, which makes the window arithmetic a pure function and the
// whole package unit-testable without a chain. Three application realms in
// the searched sources each hand-rolled this mechanism internally rather
// than importing one; see DISCOVERY.md.
//
// # The one idea
//
// An allowance is not a balance. It is a *permission with a ceiling that
// refills*. The owner says "this spender may draw at most PerPeriod per
// window, at most Total ever, until ExpiresAt, and I can revoke it now":
//
//	if err := book.Spend(id, spenderKey, now, amount); err != nil {
//		panic(err) // revoked, expired, over the window cap, over the total
//	}
//	// ... the realm moves the coins here, under its own authority
//
// Spend checks every bound and CONSUMES the allowance in the same call,
// before returning. The realm then acts. Because the realm performs the
// effect itself, no closure, callback, or capability ever crosses a realm
// boundary. spendbook cannot be handed code to run, so it cannot be
// tricked into running the wrong code.
//
// # Windows are anchored, not sliding
//
// A window is derived from a fixed origin — the Anchor set at Open — by
// integer division:
//
//	index(now) = (now - Anchor) / PeriodLength
//
// so the boundaries are the same for everyone and a spender cannot reset a
// window by choosing when to call. A sliding "PerPeriod per trailing N
// blocks" window would let a spender draw the full cap at the end of one
// trailing span and again at the start of the next; anchoring removes the
// choice. The refill is a RESET, not a carry: an unused allowance does not
// accumulate into the next window, because the point of the cap is to bound
// worst-case loss per window, and a carry would unbound it.
//
// PeriodLength == 0 means one window that never rolls: a pure lifetime
// allowance, where PerPeriod is the only cap that matters.
//
// # Amendments cannot enlarge the live window
//
// An owner who could raise PerPeriod mid-window would be able to undo the
// bound a spender is relying on, and — worse in the other direction — an
// owner who drains a relationship and then lowers terms retroactively
// could strand a spender mid-settlement. The rule here is one-sided and
// enforced in Amend:
//
//   - TIGHTER-OR-EQUAL terms apply IMMEDIATELY. Lowering a ceiling can
//     never authorize a draw that was not already authorized, so there is
//     no reason to delay it, and delaying it would make the owner's only
//     fast remedy Revoke.
//   - LOOSER terms are PENDING and take effect at the next window
//     boundary, never inside the current one.
//
// This is the same adversarial problem that r/samcrew/agent_registry_v2
// solves by locking its price while any credit entry exists; the shape
// here is a deferral rather than a lock, so terms can still move.
//
// With PeriodLength == 0 there is no next boundary, so a loosening
// amendment is refused with ErrNoBoundary rather than silently queued
// forever. PeriodLength itself is IMMUTABLE: changing it would move every
// future boundary, which is an enlargement vector wearing a different hat.
//
// # State growth
//
// Revoked allowances are removed, not archived. IDs are allocated
// monotonically and never reused, so a revoked ID can never be resurrected
// and there is nothing to keep. Live allowances are capped per Book at
// construction, so storage is bounded by maxLive regardless of how many
// allowances have ever existed. Audit history belongs in the consuming
// realm's events.
//
// An EXPIRED allowance is not self-removing, and bounded storage is not the
// same as a usable Book: Spend refuses it forever while it still holds a
// slot. Reap exists for exactly that and is permissionless, because an
// expired allowance can authorize nothing and so removing it takes nothing
// from anyone.
//
// What this package does NOT bound is how many of a Book's slots ONE owner
// may hold — maxLive is a single global figure, so any owner permitted to
// Open can exhaust it and lock out the rest. That is a policy question with
// no answer a primitive can pick (per-owner quota? first-come? owner
// whitelist?), so it is left where the authentication already lives: the
// consuming realm decides who may Open, and a Book shared across mutually
// untrusting owners needs its own per-owner cap on top of this one. Named
// here rather than implied, because "bounded" reads like "safe to share".
//
// # Consumer contract (the parts the package cannot enforce)
//
//  1. SUPPLY A REAL CLOCK. spendbook cannot verify that `now` came from
//     runtime.ChainHeight() or time.Now().Unix(). A realm that lets a
//     caller choose `now` has handed the spender the power to roll the
//     window at will, which defeats every cap in this package. Pass the
//     chain's own clock, and use the same units for the life of the Book.
//
//  2. AUTHENTICATE THE SPENDER KEY. spendbook compares the key string it
//     is given against the one recorded at Open. It cannot tell whether
//     that string is the real caller. Derive it from
//     cur.Previous().Address(), never from an argument the caller supplies.
//
//  3. SPEND BEFORE SENDING. Spend consumes the allowance and returns; the
//     realm then moves coins. Doing it in the other order means a failed
//     send leaves the allowance consumed, or a successful send leaves it
//     unconsumed — both are real losses. State first, effect second.
//
//  4. AN ALLOWANCE IS NOT CUSTODY. spendbook authorizing 100 does not mean
//     100 exists. The realm must check its own held balance separately;
//     this package bounds permission, not solvency.
package spendbook

import (
	"errors"
	"strconv"

	"gno.land/p/nt/avl/v0"
)

// MaxLiveLimit is the largest maxLive a Book may be constructed with. It
// bounds the worst-case cost of Iterate, which scans the live set.
const MaxLiveLimit = 10000

// MaxKeyLen bounds an owner or spender key. A bech32 gno address is 40
// characters; the headroom exists so a realm may namespace its keys.
const MaxKeyLen = 128

// maxInt64 is the overflow boundary for every accumulation here.
const maxInt64 = int64(1<<63 - 1)

// Errors returned by Book operations.
var (
	ErrInvalidConfig  = errors.New("spendbook: invalid book configuration")
	ErrEmptyOwner     = errors.New("spendbook: empty owner key")
	ErrEmptySpender   = errors.New("spendbook: empty spender key")
	ErrKeyTooLong     = errors.New("spendbook: key exceeds MaxKeyLen")
	ErrInvalidNow     = errors.New("spendbook: now must be non-negative")
	ErrInvalidTerms   = errors.New("spendbook: invalid terms")
	ErrInvalidAmount  = errors.New("spendbook: amount must be positive")
	ErrBookFull       = errors.New("spendbook: live allowance cap reached")
	ErrNotFound       = errors.New("spendbook: no such live allowance")
	ErrNotExpired     = errors.New("spendbook: allowance has not expired")
	ErrNotOwner       = errors.New("spendbook: caller does not own this allowance")
	ErrNotSpender     = errors.New("spendbook: caller is not this allowance's spender")
	ErrExpired        = errors.New("spendbook: allowance has expired")
	ErrNotStarted     = errors.New("spendbook: allowance has not started")
	ErrPeriodExceeded = errors.New("spendbook: amount exceeds the window cap")
	ErrTotalExceeded  = errors.New("spendbook: amount exceeds the lifetime cap")
	ErrNoBoundary     = errors.New("spendbook: no reachable next window boundary")
	ErrOverflow       = errors.New("spendbook: int64 overflow")
	ErrIDExhausted    = errors.New("spendbook: identifier space exhausted")
)

// Terms are the ceilings on an allowance. Zero has a distinct meaning in
// three of the four fields and it is never "zero allowed":
//
//	PerPeriod    > 0 required. The cap per window.
//	PeriodLength 0 means ONE window that never rolls (lifetime).
//	Total        0 means no lifetime cap.
//	ExpiresAt    0 means no expiry.
type Terms struct {
	PerPeriod    int64
	PeriodLength int64
	Total        int64
	ExpiresAt    int64
}

// valid reports whether the terms are self-consistent, given the anchor the
// allowance is (or would be) opened at.
func (t Terms) valid(anchor int64) bool {
	if t.PerPeriod <= 0 || t.PeriodLength < 0 || t.Total < 0 {
		return false
	}
	if t.ExpiresAt < 0 {
		return false
	}
	// An allowance that has already expired at its own anchor can never
	// authorize anything, so accepting it would only create a live entry
	// that every Spend refuses.
	if t.ExpiresAt != 0 && t.ExpiresAt <= anchor {
		return false
	}
	// A Total below PerPeriod is not an error -- it is a narrower lifetime
	// cap, which Spend enforces. A Total of exactly 0 is "unlimited".
	return true
}

// tighterOrEqualTo reports whether t is weakly tighter than u in every
// dimension, i.e. whether t can authorize nothing u would not have. This is
// the predicate that decides whether an amendment applies immediately.
//
// The zero-means-unlimited fields invert the comparison, which is the whole
// subtlety: Total 0 is LOOSER than any positive Total, and ExpiresAt 0 is
// LOOSER than any positive ExpiresAt. Reading those two as "smaller is
// tighter" would let an owner remove a lifetime cap and an expiry
// mid-window and call it a tightening.
func (t Terms) tighterOrEqualTo(u Terms) bool {
	if t.PeriodLength != u.PeriodLength {
		return false // immutable; see the package doc
	}
	if t.PerPeriod > u.PerPeriod {
		return false
	}
	switch {
	case u.Total == 0:
		// u was unlimited; anything is tighter or equal.
	case t.Total == 0 || t.Total > u.Total:
		return false
	}
	switch {
	case u.ExpiresAt == 0:
		// u never expired; any expiry is tighter or equal.
	case t.ExpiresAt == 0 || t.ExpiresAt > u.ExpiresAt:
		return false
	}
	return true
}

// Allowance is one owner's grant to one spender. It is returned BY VALUE:
// holders cannot reach into a Book through it.
type Allowance struct {
	ID        uint64
	Owner     string
	Spender   string
	Terms     Terms
	Anchor    int64 // window origin; also the earliest spendable instant
	CreatedAt int64

	SpentTotal  int64 // over the allowance's whole life
	SpentWindow int64 // within WindowIndex
	WindowIndex int64

	// Pending terms, applied at the next window boundary. Meaningful only
	// when HasPending is true.
	Pending    Terms
	HasPending bool
}

// IsExpired reports whether the allowance is past its expiry at now. An
// allowance with no expiry is never expired.
func (a Allowance) IsExpired(now int64) bool {
	return a.Terms.ExpiresAt != 0 && now >= a.Terms.ExpiresAt
}

// windowIndex returns the anchored window number containing now. A lifetime
// allowance (PeriodLength == 0) is always in window 0.
//
// now < Anchor cannot reach here: every caller rejects it first with
// ErrNotStarted, which keeps this division away from negative numerators
// where Go's truncation-toward-zero would fold two windows into one.
func (a Allowance) windowIndex(now int64) int64 {
	if a.Terms.PeriodLength == 0 {
		return 0
	}
	return (now - a.Anchor) / a.Terms.PeriodLength
}

// nextBoundary returns the instant window idx+1 begins, and whether that
// instant is reachable at all.
//
// Unreachable has three causes and they collapse to the same answer, which is
// why this returns a bool rather than an error: a lifetime allowance has no
// boundary by construction, and an arithmetically unrepresentable boundary
// (PeriodLength so large, or the clock so far along, that Anchor + steps *
// PeriodLength overflows int64) is one no clock will ever reach. Computing it
// unguarded would wrap to a small number and report a boundary in the PAST,
// which is the dangerous direction: Amend would queue a loosening as though
// it were about to take effect.
func (a Allowance) nextBoundary(idx int64) (int64, bool) {
	pl := a.Terms.PeriodLength
	if pl == 0 || idx < 0 || idx == maxInt64 {
		return 0, false
	}
	steps := idx + 1
	if steps > maxInt64/pl {
		return 0, false
	}
	off := steps * pl
	if off > maxInt64-a.Anchor {
		return 0, false
	}
	return a.Anchor + off, true
}

// at computes the allowance's effective state at now WITHOUT mutating it:
// the terms in force, the window it falls in, and how much has been spent
// within that window.
//
// Spend and Remaining BOTH go through this one function. That is deliberate
// -- a read that answered "how much is left" with its own copy of the
// rollover and amendment logic would be a second implementation of the
// rule, free to disagree with the one that enforces it, and the
// disagreement would surface as an allowance that reports more than it
// honors (or honors more than it reports).
func (a Allowance) at(now int64) (Terms, int64, int64) {
	idx := a.windowIndex(now)
	if idx == a.WindowIndex {
		return a.Terms, idx, a.SpentWindow
	}
	// The window has rolled. A pending amendment takes effect exactly here,
	// and the in-window spend resets -- it does not carry.
	terms := a.Terms
	if a.HasPending {
		terms = a.Pending
	}
	return terms, idx, 0
}

// Remaining reports how much the spender may draw right now: the lesser of
// what the current window leaves and what the lifetime cap leaves. It is 0
// for an allowance that is expired, not yet started, or fully drawn.
//
// It is a projection, not a reservation. Nothing is held, and the figure can
// change in the same block if someone else's call advances the clock past a
// boundary.
func (a Allowance) Remaining(now int64) int64 {
	if now < a.Anchor || a.IsExpired(now) {
		return 0
	}
	terms, _, spentWindow := a.at(now)
	left := terms.PerPeriod - spentWindow
	if left < 0 {
		// Reachable: a tightening amendment can drop PerPeriod below what
		// the window already spent. The allowance is drawn, not negative.
		left = 0
	}
	if terms.Total != 0 {
		lifeLeft := terms.Total - a.SpentTotal
		if lifeLeft < 0 {
			lifeLeft = 0
		}
		if lifeLeft < left {
			left = lifeLeft
		}
	}
	return left
}

// Book holds the live allowances of one consuming realm. The zero value is
// not usable; construct with New.
type Book struct {
	maxLive int
	nextID  uint64    // never decreases; IDs are never reused
	live    *avl.Tree // padded id -> Allowance
}

// New returns an empty Book. maxLive caps simultaneously live allowances
// and must be in [1, MaxLiveLimit].
func New(maxLive int) (*Book, error) {
	if maxLive < 1 || maxLive > MaxLiveLimit {
		return nil, ErrInvalidConfig
	}
	return &Book{maxLive: maxLive, nextID: 1, live: avl.NewTree()}, nil
}

// MustNew is New but panics on error.
func MustNew(maxLive int) *Book {
	b, err := New(maxLive)
	if err != nil {
		panic(err)
	}
	return b
}

// MaxLive returns the Book's cap on simultaneously live allowances.
func (b *Book) MaxLive() int { return b.maxLive }

// Count returns the number of live allowances.
func (b *Book) Count() int { return b.live.Size() }

// key pads an id to a fixed width so avl's lexical order matches numeric
// order. 20 digits covers the whole uint64 range.
func key(id uint64) string {
	s := strconv.FormatUint(id, 10)
	for len(s) < 20 {
		s = "0" + s
	}
	return s
}

func checkKeys(owner, spender string) error {
	if owner == "" {
		return ErrEmptyOwner
	}
	if spender == "" {
		return ErrEmptySpender
	}
	if len(owner) > MaxKeyLen || len(spender) > MaxKeyLen {
		return ErrKeyTooLong
	}
	return nil
}

// Open records a new allowance and returns its id. now becomes the window
// anchor and the earliest instant the spender may draw.
//
// An owner may open several allowances for the same spender; they are
// independent, and the ids are what tell them apart. spendbook does not
// merge or deduplicate them, because "one allowance per pair" is a policy
// some consuming realms want and others do not, and a primitive that
// decided it here could not be talked out of it.
func (b *Book) Open(owner, spender string, now int64, terms Terms) (uint64, error) {
	if err := checkKeys(owner, spender); err != nil {
		return 0, err
	}
	if now < 0 {
		return 0, ErrInvalidNow
	}
	if !terms.valid(now) {
		return 0, ErrInvalidTerms
	}
	if b.live.Size() >= b.maxLive {
		return 0, ErrBookFull
	}
	if b.nextID == 0 {
		return 0, ErrIDExhausted
	}
	id := b.nextID
	b.nextID++
	b.live.Set(key(id), Allowance{
		ID:        id,
		Owner:     owner,
		Spender:   spender,
		Terms:     terms,
		Anchor:    now,
		CreatedAt: now,
	})
	return id, nil
}

// get fetches a live allowance by id.
//
// avl's Get returns a bare `any` with no found flag, so absence is a nil
// value. That is sound here only because nothing nil is ever stored: Set is
// called in exactly three places and all three pass an Allowance value.
func (b *Book) get(id uint64) (Allowance, bool) {
	v := b.live.Get(key(id))
	if v == nil {
		return Allowance{}, false
	}
	a, ok := v.(Allowance)
	if !ok {
		return Allowance{}, false
	}
	return a, true
}

// Get returns a copy of a live allowance.
func (b *Book) Get(id uint64) (Allowance, error) {
	a, ok := b.get(id)
	if !ok {
		return Allowance{}, ErrNotFound
	}
	return a, nil
}

// Remaining reports what the spender of id may draw at now, or 0 if there
// is no such live allowance. A caller that must distinguish "nothing left"
// from "no such allowance" should use Get.
func (b *Book) Remaining(id uint64, now int64) int64 {
	a, ok := b.get(id)
	if !ok {
		return 0
	}
	return a.Remaining(now)
}

// Spend consumes amount from allowance id on behalf of spender and returns
// nil if every bound permits it. The caller then performs its own effect.
//
// On any error NOTHING is consumed. The write happens once, after the last
// check, so a refused Spend leaves the book exactly as it was.
func (b *Book) Spend(id uint64, spender string, now int64, amount int64) error {
	if now < 0 {
		return ErrInvalidNow
	}
	if amount <= 0 {
		return ErrInvalidAmount
	}
	a, ok := b.get(id)
	if !ok {
		return ErrNotFound
	}
	if a.Spender != spender {
		return ErrNotSpender
	}
	if now < a.Anchor {
		return ErrNotStarted
	}
	if a.IsExpired(now) {
		return ErrExpired
	}

	terms, idx, spentWindow := a.at(now)

	// Window cap. Checked as a subtraction so the sum cannot overflow:
	// spentWindow and PerPeriod are both >= 0 and PerPeriod > 0.
	if amount > terms.PerPeriod-spentWindow {
		return ErrPeriodExceeded
	}
	// Lifetime cap.
	if terms.Total != 0 && amount > terms.Total-a.SpentTotal {
		return ErrTotalExceeded
	}
	// SpentTotal is unbounded when Total == 0, so it is the one
	// accumulation that can genuinely reach the int64 ceiling.
	if a.SpentTotal > maxInt64-amount {
		return ErrOverflow
	}

	a.Terms = terms
	if idx != a.WindowIndex {
		a.HasPending = false
		a.Pending = Terms{}
	}
	a.WindowIndex = idx
	a.SpentWindow = spentWindow + amount
	a.SpentTotal += amount
	b.live.Set(key(id), a)
	return nil
}

// Revoke removes an allowance. Only its owner may revoke, and it takes
// effect immediately -- there is no window to wait for, because revocation
// is the owner's remedy and a delayed remedy is not one.
//
// The id is not reused, so a revoked allowance cannot be resurrected: a
// later Spend on it returns ErrNotFound forever.
func (b *Book) Revoke(id uint64, owner string) error {
	a, ok := b.get(id)
	if !ok {
		return ErrNotFound
	}
	if a.Owner != owner {
		return ErrNotOwner
	}
	b.live.Remove(key(id))
	return nil
}

// Amend changes an allowance's terms. Only its owner may amend.
//
// PeriodLength is immutable and must be passed unchanged. Terms that are
// weakly tighter in every dimension apply immediately; anything looser
// becomes pending and takes effect at the next window boundary. A lifetime
// allowance has no next boundary, so a loosening amendment on one is
// refused with ErrNoBoundary.
//
// The returned bool reports whether the amendment applied immediately
// (true) or was queued (false). A caller that ignores it cannot tell
// whether the new ceiling is in force, which is exactly the thing worth
// knowing.
func (b *Book) Amend(id uint64, owner string, now int64, terms Terms) (bool, error) {
	if now < 0 {
		return false, ErrInvalidNow
	}
	a, ok := b.get(id)
	if !ok {
		return false, ErrNotFound
	}
	if a.Owner != owner {
		return false, ErrNotOwner
	}
	if now < a.Anchor {
		return false, ErrNotStarted
	}
	if a.IsExpired(now) {
		return false, ErrExpired
	}
	// Validated against the ANCHOR rather than now, which is the LOOSER of
	// the two and is deliberate. valid() only needs ExpiresAt to be after the
	// window origin; an owner naming an expiry between the anchor and now is
	// tightening the allowance until it is dead, which is their prerogative.
	// Revoke is the cleaner way to say that, and Reap then reclaims the slot.
	if !terms.valid(a.Anchor) {
		return false, ErrInvalidTerms
	}
	if terms.PeriodLength != a.Terms.PeriodLength {
		return false, ErrInvalidTerms
	}

	// Roll the window first if the clock has moved past a boundary, so an
	// amendment made after a quiet stretch is judged against the terms
	// actually in force rather than the ones a stale record still holds.
	cur, idx, spentWindow := a.at(now)
	if idx != a.WindowIndex {
		a.Terms = cur
		a.WindowIndex = idx
		a.SpentWindow = spentWindow
		a.HasPending = false
		a.Pending = Terms{}
	}

	if terms.tighterOrEqualTo(a.Terms) {
		a.Terms = terms
		// A tightening supersedes a queued loosening. Leaving it queued
		// would mean the owner's tightening silently expires at the next
		// boundary and the looser terms they just replaced come back.
		a.HasPending = false
		a.Pending = Terms{}
		b.live.Set(key(id), a)
		return true, nil
	}

	// A loosening is only queueable if the boundary it waits for will arrive
	// while the allowance is still alive. Queueing one that cannot be reached
	// would report "accepted, pending" for terms that never take effect --
	// the owner's amendment silently discarded, which is the failure mode
	// this package is least able to explain after the fact.
	//
	// Two ways it is unreachable. The allowance has no boundary at all
	// (PeriodLength == 0, or an unrepresentable one), or the current terms
	// expire at or before the next boundary. The second is reachable in
	// ordinary use: a tightening of ExpiresAt applies IMMEDIATELY, so an
	// owner can tighten the expiry below the next boundary and then loosen
	// PerPeriod, and without this check the second call would be accepted
	// against a window that never opens.
	nb, ok := a.nextBoundary(a.WindowIndex)
	if !ok {
		return false, ErrNoBoundary
	}
	if a.Terms.ExpiresAt != 0 && nb >= a.Terms.ExpiresAt {
		return false, ErrNoBoundary
	}
	a.Pending = terms
	a.HasPending = true
	b.live.Set(key(id), a)
	return false, nil
}

// Reap removes an allowance that has expired at now, and may be called by
// anyone. It returns ErrNotFound for an unknown id and ErrNotExpired for one
// that is still alive.
//
// Permissionless on purpose, and the reasoning is the whole justification:
// an expired allowance can never authorize another draw, so removing it takes
// nothing from the owner and grants nothing to the caller. Without it an
// expiry is a slow leak against maxLive -- Spend refuses the dead allowance
// forever while it holds a slot, so a Book shared between owners could fill
// with corpses and refuse new Opens, and the only remedy would be the owner
// of each corpse noticing and calling Revoke.
//
// This relies on `now` exactly as much as Spend does. A realm that lets a
// caller choose `now` has already broken consumer contract item 1, and such a
// realm would let a caller reap a LIVE allowance by naming a future instant.
func (b *Book) Reap(id uint64, now int64) error {
	if now < 0 {
		return ErrInvalidNow
	}
	a, ok := b.get(id)
	if !ok {
		return ErrNotFound
	}
	if !a.IsExpired(now) {
		return ErrNotExpired
	}
	b.live.Remove(key(id))
	return nil
}

// Iterate calls fn for every live allowance in id order, stopping early if
// fn returns true. The allowance is passed by value, so fn cannot mutate
// the book through it.
func (b *Book) Iterate(fn func(Allowance) bool) {
	b.live.Iterate("", "", func(_ string, v any) bool {
		return fn(v.(Allowance))
	})
}
